=== Method: calc (AbstractMethod) ===
// Purpose of this class to provide the required brake hold request in casse Hold (or Drive Off is not yet performed)
// is requested by the function
// In principle it represents the general core requirement "CSM should try to hold vehicle in case Hold is requested"

// As long as hold is not performed the available system pressure is also considered for target brake request
if	(CsmHoldBrkHoldActive == false
	&&	CsmHoldRolloutActive == false
	&&	CsmHoldBrkIncActive == false // op-fix: added
	&&	OperationPointConsiderSyst == true // op-fix: added -> system only in case no ldm request
	)
{
	CsmACurBrk = (CsmABrkSys).min(CsmAActConfirmedReq); // Actuated System level or maxDrv/LDM request level
}
else
{
	CsmACurBrk = CsmAActConfirmedReq; // maxDrv/LDM request level
}

// Enable transition of target brake request
if(CsmHoldEnableRequestTransition == true)
{
	CsmHoldABrkThrMax = CsmABrkThrMax.min(CsmCfgABrkThrMax).min(CsmAActConfirmedReq); // CSM level or Function level or maxDrv/LDM request level
}else
{
	CsmHoldABrkThrMax = CsmABrkThrMax.min(CsmCfgABrkThrMax); // CSM level or Function level
}

// Determine if brake hold shall be enabled

if(CsmHoldBrkHoldReqActive > 0)			// In case Hold is requested
{
	CsmHoldBrkHoldActive = true;
	CsmHoldBrkHoldForDriveOffActive = false;
	
	CsmHoldBrkHoldATarThrMaxFreezed = (CsmHoldABrkThrMax.max(CsmACurBrk)).min(CsmHoldBrkHoldATarThrMaxFreezed.min(CsmHoldATarBrk));
	
	CsmHoldBrkHoldATarBrk = CsmHoldATarBrk.min((CsmACurBrk.max(CsmHoldBrkHoldATarThrMaxFreezed)).min(CsmHoldBrkHoldATarBrk.max(CsmHoldBrkHoldATarThrMaxFreezed)));
	if(CsmHoldOperationPointCorrection == true)
	{
		CsmHoldBrkHoldATarBrk = CsmAActConfirmedReq.max(CsmHoldBrkHoldATarBrk);
	}
	CsmHoldBrkHoldATarBrk = CsmHoldBrkHoldATarBrk.min(0);
}
else if(CsmHoldStandbyReqActive > 0				// In case Hold is requested
	&&	(	CsmHoldBrkHoldActive	== true		// AND CSM is already in Brake Hold State
		||	CsmHoldRolloutActive	== true))	// OR rollout is active
{
	CsmHoldBrkHoldActive = true;
	CsmHoldBrkHoldForDriveOffActive = false;
	
	CsmHoldBrkHoldATarThrMaxFreezed = (CsmHoldABrkThrMax.max(CsmACurBrk)).min(CsmHoldBrkHoldATarThrMaxFreezed.min(CsmHoldATarBrk));
	
	CsmHoldBrkHoldATarBrk = CsmHoldATarBrk.min((CsmACurBrk.max(CsmHoldBrkHoldATarThrMaxFreezed)).min(CsmHoldBrkHoldATarBrk.max(CsmHoldBrkHoldATarThrMaxFreezed)));
	if(CsmHoldOperationPointCorrection == true)
	{
		CsmHoldBrkHoldATarBrk = CsmAActConfirmedReq.max(CsmHoldBrkHoldATarBrk);
	}
	CsmHoldBrkHoldATarBrk = CsmHoldBrkHoldATarBrk.min(0);
}
else if(CsmHoldDriveReqActive > 0	// if drive off is requested
	&&	(	(	CsmHoldBrkHoldActive	== true		// AND CSM is already in Brake Hold State
			&&	CsmHoldDriveOffActive	== false)
		||	CsmHoldRolloutActive == true))
{
	CsmHoldBrkHoldActive = true;
	CsmHoldBrkHoldForDriveOffActive = true;
	
	CsmHoldBrkHoldATarThrMaxFreezed = (CsmHoldABrkThrMax.max(CsmACurBrk)).min(CsmHoldBrkHoldATarThrMaxFreezed.min(CsmHoldATarBrk));
	
	CsmHoldBrkHoldATarBrk = CsmHoldATarBrk.min((CsmACurBrk.max(CsmHoldBrkHoldATarThrMaxFreezed)).min(CsmHoldBrkHoldATarBrk.max(CsmHoldBrkHoldATarThrMaxFreezed)));
	if(CsmHoldOperationPointCorrection == true)
	{
		CsmHoldBrkHoldATarBrk = CsmAActConfirmedReq.max(CsmHoldBrkHoldATarBrk);
	}
	CsmHoldBrkHoldATarBrk = CsmHoldBrkHoldATarBrk.min(0);
	
}else
{
	CsmHoldBrkHoldActive = false;
	CsmHoldBrkHoldForDriveOffActive = false;
	CsmHoldBrkHoldATarBrk = 0;
	CsmHoldBrkHoldATarThrMaxFreezed = (CsmHoldBrkHoldATarThrMaxFreezed.max(CsmHoldATarBrk)).min(CsmHoldABrkThrMax);
}
	


=== Method: CsmHoldBrkHoldActive (AbstractMethod) ===
return CsmHoldBrkHoldActive;


=== Method: CsmHoldBrkHoldATarBrk (AbstractMethod) ===
return CsmHoldBrkHoldATarBrk;


=== Method: CsmHoldBrkHoldForDriveOffActive (AbstractMethod) ===
return CsmHoldBrkHoldForDriveOffActive;
